import{_ as a,a0 as i,w as l,s as p,ao as h,I as n,x as t,a1 as r,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"在 Linux 中为非 SSH 用户配置 SFTP 环境 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中为非 SSH 用户配置 SFTP 环境 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中为非 SSH 用户配置 SFTP 环境 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中为非 SSH 用户配置 SFTP 环境 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140723 How to configure chroot SFTP in Linux","title":"在 Linux 中为非 SSH 用户配置 SFTP 环境","tag":"201408","desc":""},"relativePath":"201408/20140723 How to configure chroot SFTP in Linux.md","filePath":"[post].md"}'),d={name:"201408/20140723 How to configure chroot SFTP in Linux.md"};function c(u,o,f,g,m,x){const s=i("Link");return l(),p("div",null,[o[13]||(o[13]=h(`<h1 id="在-linux-中为非-ssh-用户配置-sftp-环境" tabindex="-1">在 Linux 中为非 SSH 用户配置 SFTP 环境 <a class="header-anchor" href="#在-linux-中为非-ssh-用户配置-sftp-环境" aria-label="Permalink to “在 Linux 中为非 SSH 用户配置 SFTP 环境”">​</a></h1><p>在<strong>某些环境</strong>中，系统管理员想要允许极少数用户在可以传输文件到Linux机器中，但是不允许使用 SSH。要实现这一目的，我们可以使用<strong>SFTP</strong>，并为其构建chroot环境。</p><h3 id="sftp-chroot背景" tabindex="-1">SFTP &amp; chroot背景： <a class="header-anchor" href="#sftp-chroot背景" aria-label="Permalink to “SFTP &amp; chroot背景：”">​</a></h3><p><strong>SFTP</strong>是指<strong>SSH文件传输协议（SSH File Transfer protocol）或安全文件传输协议（Secure File Transfer Protocol）</strong>，它提供了可信数据流下的文件访问、文件传输以及文件管理功能。当我们为SFTP配置chroot环境后，只有被许可的用户可以访问，并被限制到他们的<strong>家目录</strong>中，换言之：被许可的用户将处于牢笼环境中，在此环境中它们甚至不能切换它们的目录。</p><p>在本文中，我们将配置<strong>RHEL 6.X</strong> 和 <strong>CentOS 6.X中的SFTP Chroot环境</strong>。我们开启一个用户帐号‘<strong>Jack</strong>’，该用户将被允许在Linux机器上传输文件，但没有ssh访问权限。</p><h3 id="步骤-1-创建组" tabindex="-1">步骤：1 创建组 <a class="header-anchor" href="#步骤-1-创建组" aria-label="Permalink to “步骤：1  创建组”">​</a></h3><pre><code>[root@localhost ~]# groupadd  sftp_users
</code></pre><h3 id="步骤-2-分配附属组-sftp-users-给用户" tabindex="-1">步骤：2 分配附属组(sftp_users)给用户 <a class="header-anchor" href="#步骤-2-分配附属组-sftp-users-给用户" aria-label="Permalink to “步骤：2 分配附属组(sftp_users)给用户”">​</a></h3><p>如果用户在系统上不存在，使用以下命令创建（ LCTT 译注：这里给用户指定了一个不能登录的 shell，以防止通过 ssh 登录）：</p><pre><code>[root@localhost ~]# useradd  -G sftp_users  -s /sbin/nologin  jack
[root@localhost ~]# passwd jack
</code></pre><p>对于<strong>已经存在的用户</strong>，使用以下usermod命令进行修改：</p><pre><code>[root@localhost ~]# usermod –G sftp_users  -s /sbin/nologin  jack
</code></pre><p><strong>注意</strong>：如果你想要修改用户的<strong>默认家目录</strong>，那么可以在useradd和usermod命令中使用‘<strong>-d</strong>’选项，并设置<strong>合适的权限</strong>。</p><h3 id="步骤-3-现在编辑配置文件-etc-ssh-sshd-config" tabindex="-1">步骤：3 现在编辑配置文件 “/etc/ssh/sshd_config” <a class="header-anchor" href="#步骤-3-现在编辑配置文件-etc-ssh-sshd-config" aria-label="Permalink to “步骤：3 现在编辑配置文件 “/etc/ssh/sshd_config””">​</a></h3><pre><code># vi /etc/ssh/sshd_config
#comment out the below line and add a line like below
#Subsystem sftp /usr/libexec/openssh/sftp-server
Subsystem sftp internal-sftp

# add Below lines  at the end of file
  Match Group sftp_users
  X11Forwarding no
  AllowTcpForwarding no
  ChrootDirectory %h                      
  ForceCommand internal-sftp
</code></pre><h4 id="此处" tabindex="-1">此处： <a class="header-anchor" href="#此处" aria-label="Permalink to “此处：”">​</a></h4><ul><li><strong>Match Group sftp_users</strong> – 该参数指定以下的行将仅仅匹配sftp_users组中的用户</li><li><strong>ChrootDirectory %h</strong> – 该参数指定用户验证后用于chroot环境的路径（默认的用户家目录）。对于用户 Jack，该路径就是/home/jack。</li><li><strong>ForceCommand internal-sftp</strong> – 该参数强制执行内部sftp，并忽略任何~/.ssh/rc文件中的命令。</li></ul><p>重启ssh服务</p><pre><code># service sshd restart
</code></pre><h3 id="步骤-4-设置权限" tabindex="-1">步骤：4 设置权限： <a class="header-anchor" href="#步骤-4-设置权限" aria-label="Permalink to “步骤：4 设置权限：”">​</a></h3><pre><code>[root@localhost ~]# chmod 755 /home/jack
[root@localhost ~]# chown root /home/jack
[root@localhost ~]# chgrp -R sftp_users /home/jack
</code></pre><p>如果你想要允许jack用户上传文件，那么创建一个上传文件夹，设置权限如下：</p><pre><code>[root@localhost jack]# mkdir /home/jack/upload
[root@localhost jack]# chown jack. /home/jack upload/
</code></pre><h3 id="步骤-5-现在尝试访问系统并进行测试" tabindex="-1">步骤：5 现在尝试访问系统并进行测试 <a class="header-anchor" href="#步骤-5-现在尝试访问系统并进行测试" aria-label="Permalink to “步骤：5  现在尝试访问系统并进行测试”">​</a></h3><p>尝试通过ssh访问系统</p><p><img src="http://www.linuxtechi.com/wp-content/uploads/2014/07/ssh-try.png" alt=""></p><p>正如下图所示，用户jack通过SFTP登录，而且因为chroot环境不能切换目录。</p><p><img src="http://www.linuxtechi.com/wp-content/uploads/2014/07/sftp-login.png" alt=""></p><p>现在进行<strong>上传和下载</strong>测试，如下图：</p><p><img src="http://www.linuxtechi.com/wp-content/uploads/2014/07/sftp-upload-download.png" alt=""></p><p>正如上图所示，jack用户的上传下载功能都工作得很好。</p><hr>`,32)),n("p",null,[o[1]||(o[1]=t("via: ",-1)),r(s,{href:"http://www.linuxtechi.com/configure-chroot-sftp-in-linux/"},{default:e(()=>[...o[0]||(o[0]=[t("http://www.linuxtechi.com/configure-chroot-sftp-in-linux/",-1)])]),_:1})]),n("p",null,[o[3]||(o[3]=t("原文作者：",-1)),r(s,{href:"http://www.linuxtechi.com/author/pradeep/"},{default:e(()=>[...o[2]||(o[2]=[t("Pradeep Kumar",-1)])]),_:1})]),n("p",null,[o[6]||(o[6]=t("译者：",-1)),r(s,{href:"https://github.com/GOLinux"},{default:e(()=>[...o[4]||(o[4]=[t("GOLinux",-1)])]),_:1}),o[7]||(o[7]=t(" 校对：",-1)),r(s,{href:"https://github.com/wxy"},{default:e(()=>[...o[5]||(o[5]=[t("wxy",-1)])]),_:1})]),n("p",null,[o[10]||(o[10]=t("本文由 ",-1)),r(s,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...o[8]||(o[8]=[t("LCTT",-1)])]),_:1}),o[11]||(o[11]=t(" 原创翻译，",-1)),r(s,{href:"http://linux.cn/"},{default:e(()=>[...o[9]||(o[9]=[t("Linux中国",-1)])]),_:1}),o[12]||(o[12]=t(" 荣誉推出",-1))])])}const P=a(d,[["render",c]]);export{w as __pageData,P as default};
